#include <cstdio>
#include <string>

int main() {
    int n = 0;
    if (std::scanf("%d", &n) != 1) return 1;
    if (n < 1 || n > 50) return 1;
    long long cpp_count = 0;
    long long python_count = 0;
    long long other_count = 0;
    for (int i = 0; i < n; i++) {
        char name[64];
        char category[32];
        if (std::scanf("%63s %31s", name, category) != 2) return 1;
        std::string kind(category);
        if (kind == "cpp") {
            cpp_count++;
        } else if (kind == "python") {
            python_count++;
        } else if (kind == "other") {
            other_count++;
        } else {
            return 1;
        }
    }
    std::printf("cpp=%lld python=%lld other=%lld\n", cpp_count, python_count, other_count);
    return 0;
}
